type View = "home" | "login" | "signup" | "dashboard" | "problems" | "practice" | "analysis" | "analytics" | "history";

type InterviewQuestion = { question: string; answer: string };
type Problem = { title: string; topic: string; difficulty: "Easy" | "Medium" | "Hard"; solved: boolean; attempts: number; time: string };
type ProblemDetail = {
  statement: string; input: string; output: string; why: string; constraints: string[]; lens: string;
  starterCode: string; brute: string; optimal: string; time: string; space: string; questions: InterviewQuestion[];
};

type StoredUser = { fullName: string; username: string; email: string; password: string };
const USER_STORAGE_KEY = "syntaxcompilefit-user";
const readStoredUser = (): StoredUser | null => { try { const raw = localStorage.getItem(USER_STORAGE_KEY); return raw ? JSON.parse(raw) as StoredUser : null; } catch { return null; } };
const userInitials = (fullName: string) => fullName.split(" ").filter(Boolean).map(part => part[0]).join("").slice(0, 2).toUpperCase() || "ST";

