type ExecutionResult = { ok: boolean; output: string; error?: string; time: string; memory: string };
const evaluateCode = (source: string, problem: Problem, detail: ProblemDetail): ExecutionResult => {
  const code = source.trim();
  if (!code) return { ok: false, output: "", error: "Compilation error: your editor is empty.", time: "0 ms", memory: "0 MB" };
  if (!/class\s+(Solution|MinStack|MyQueue|LRUCache)/.test(code)) return { ok: false, output: "", error: "Compilation error: define the expected Java class before running.", time: "0 ms", memory: "0 MB" };
  if (code === detail.starterCode.trim()) return { ok: false, output: detail.output, error: `Sample test failed for ${problem.title}. Replace the starter return value with your solution.`, time: "1 ms", memory: "8 MB" };
  return { ok: true, output: detail.output, time: problem.time === "—" ? "48 ms" : problem.time, memory: "12 MB" };
};
const problems: Problem[] = [...baseProblems, ...additionalProblems];
const addInterviewQuestions = (title: string, detail: ProblemDetail): ProblemDetail => ({ ...detail, questions: [...detail.questions, { question: `What is the first edge case you would test for ${title}?`, answer: "Start with the smallest valid input, then test duplicates, boundary values, and a case where the answer is missing or appears at the end." }, { question: `How would you communicate the correctness of ${title}?`, answer: "State the invariant, explain why each update preserves it, and connect the final state to the requested output." }, { question: `How could ${title} change with larger input?`, answer: "Keep the same correctness argument but watch the target complexity, integer ranges, memory limits, and whether the input should be processed as a stream." }, { question: `What common bug appears in ${title}?`, answer: "The common mistakes are off-by-one boundaries, forgetting an empty input, and updating the answer before maintaining the algorithm's invariant." }, { question: `What alternative data structure could help with ${title}?`, answer: "The alternative depends on the constraints, but I would compare lookup cost, ordering requirements, update cost, and auxiliary memory before changing the structure." }, { question: `What would you improve after solving ${title}?`, answer: "I would add adversarial tests, confirm the complexity on the largest input, and make the invariant visible through clear names and a short explanation." }, { question: `What follow-up requirement would change ${title}?`, answer: "Returning the actual construction, supporting online input, or reducing memory would change the implementation while keeping the same core correctness contract." }].slice(0, 10) });
const problemDetails: Record<string, ProblemDetail> = Object.fromEntries(Object.entries({ ...baseProblemDetails, ...additionalDetails }).map(([title, detail]) => [title, addInterviewQuestions(title, detail)])) as Record<string, ProblemDetail>;
const getProblemDetails = (problem: Problem) => problemDetails[problem.title] ?? problemDetails["Two Sum"];

