function Brand({ onClick }: { onClick: () => void }) {
  return <button className="brand" onClick={onClick}><span className="brand-mark">{`{_}`}</span><span>Syntax<span>Compile</span>Fit</span></button>;
}

function Pill({ children, tone = "neutral" }: { children: React.ReactNode; tone?: "neutral" | "mint" | "amber" | "purple" }) {
  return <span className={`pill pill-${tone}`}>{children}</span>;
}

function StatCard({ label, value, note, icon: Icon, tone }: { label: string; value: string; note: string; icon: typeof Target; tone: string }) {
  return <div className={`stat-card ${tone}`}><div className="stat-top"><span>{label}</span><span className="stat-icon"><Icon size={16} /></span></div><strong>{value}</strong><small>{note}</small></div>;
}

