function AuthPage({ mode, go, onAuth }: { mode: "login" | "signup"; go: (view: View) => void; onAuth: (user: StoredUser) => void }) {
  const isSignup = mode === "signup";
  const [fullName, setFullName] = useState(""); const [username, setUsername] = useState(""); const [email, setEmail] = useState(""); const [password, setPassword] = useState(""); const [confirmPassword, setConfirmPassword] = useState(""); const [error, setError] = useState("");
  const submit = (event: React.FormEvent) => { event.preventDefault(); setError(""); const saved = readStoredUser(); if (isSignup) { if (!fullName.trim() || !username.trim() || !email.trim() || password.length < 6) { setError("Please complete every field. Passwords must be at least 6 characters."); return; } if (password !== confirmPassword) { setError("Passwords do not match."); return; } const user = { fullName: fullName.trim(), username: username.trim(), email: email.trim().toLowerCase(), password }; localStorage.setItem(USER_STORAGE_KEY, JSON.stringify(user)); onAuth(user); return; } const identifier = email.trim().toLowerCase(); if (!saved || (saved.email !== identifier && saved.username.toLowerCase() !== identifier) || saved.password !== password) { setError("We couldn't match those details. Sign up first or check your password."); return; } onAuth(saved); };
  return <div className="auth-page"><div className="auth-decoration"><div className="auth-orbit" /><div className="auth-code"><span>01</span> understand();<br /><span>02</span> explain();<br /><span>03</span> improve();</div><div className="auth-quote"><Sparkles size={16} /><b>Practice with purpose.</b><small>Every attempt becomes interview confidence.</small></div></div><div className="auth-panel"><Brand onClick={() => go("home")} /><div className="auth-content"><div className="section-kicker">{isSignup ? "CREATE YOUR WORKSPACE" : "WELCOME BACK"}</div><h1>{isSignup ? "Build your practice loop." : "Pick up where you left off."}</h1><p>{isSignup ? "Create an account and make every coding session count." : "Log in to see your personal progress, submissions and interview prep."}</p><form onSubmit={submit} className="auth-form">{isSignup && <><label>Full name<input value={fullName} onChange={e => setFullName(e.target.value)} placeholder="e.g. Priya Sharma" /></label><label>Username<input value={username} onChange={e => setUsername(e.target.value)} placeholder="e.g. priyasharma" /></label></>}<label>Email or username<input value={email} onChange={e => setEmail(e.target.value)} placeholder="you@example.com" autoComplete="username" /></label><label>Password<input type="password" value={password} onChange={e => setPassword(e.target.value)} placeholder={isSignup ? "At least 6 characters" : "Your password"} autoComplete={isSignup ? "new-password" : "current-password"} /></label>{isSignup && <label>Confirm password<input type="password" value={confirmPassword} onChange={e => setConfirmPassword(e.target.value)} placeholder="Repeat your password" autoComplete="new-password" /></label>}{error && <div className="auth-error">{error}</div>}<button className="btn btn-primary auth-submit" type="submit">{isSignup ? "Create account" : "Log in"} <ArrowRight size={16} /></button></form><div className="auth-switch">{isSignup ? "Already have an account?" : "New to SyntaxCompileFit?"} <button onClick={() => go(isSignup ? "login" : "signup")}>{isSignup ? "Log in" : "Sign up"}</button></div><small className="auth-note">Prototype accounts persist in this browser for your next visit.</small></div></div></div>;
}

function AppShell({ view, setView, children, user, onLogout }: { view: View; setView: (view: View) => void; children: React.ReactNode; user: StoredUser | null; onLogout: () => void }) {
  const [mobileOpen, setMobileOpen] = useState(false); const displayName = user?.fullName || "Student";
  return <div className="app-shell"><aside className={`sidebar ${mobileOpen ? "is-open" : ""}`}><div className="side-brand"><Brand onClick={() => setView("home")} /><button className="side-close" onClick={() => setMobileOpen(false)}><X size={18} /></button></div><div className="side-label">WORKSPACE</div><nav className="side-nav">{navItems.map(({ id, label, icon: Icon }) => <button className={view === id || (view === "analysis" && id === "practice") ? "active" : ""} key={id} onClick={() => { setView(id); setMobileOpen(false); }}><Icon size={17} />{label}{id === "practice" && <span className="live-dot" />}</button>)}</nav><div className="side-label side-label-space">YOUR PROGRESS</div><div className="streak-card"><div className="streak-flame"><Flame size={17} /></div><div><b>7 day streak</b><small>Best: 12 days</small></div><ChevronDown size={15} /></div><div className="side-bottom"><button><Settings2 size={16} />Settings</button><button className="profile" onClick={onLogout} title="Log out"><span className="profile-avatar">{userInitials(displayName)}</span><span><b>{displayName}</b><small>{user?.email || "Guest account"}</small></span><ChevronDown size={15} /></button></div></aside><main className="app-main"><header className="app-header"><button className="mobile-menu" onClick={() => setMobileOpen(true)}><Menu size={20} /></button><div className="crumb"><span>Workspace</span><ArrowRight size={13} /> <b>{view === "dashboard" ? "Overview" : view === "practice" ? "Practice room" : view === "analysis" ? "Solution analysis" : view[0].toUpperCase() + view.slice(1)}</b></div><div className="header-actions"><button className="icon-btn"><Search size={17} /></button><button className="help-btn">? <span>Help center</span></button><span className="header-avatar">{userInitials(displayName)}</span></div></header>{children}</main></div>;
}

function Dashboard({ go, user }: { go: (view: View) => void; user: StoredUser | null }) {
  return <div className="screen dashboard-screen"><div className="welcome-row"><div><div className="section-kicker">TUESDAY, OCTOBER 7, 2026</div><h1>Welcome back, {user?.fullName || "Student"} <span className="wave">✦</span></h1><p>Ready to sharpen your coding and interview skills?</p></div><button className="btn btn-primary" onClick={() => go("problems")}><CirclePlay size={16} /> Continue practice</button></div><div className="stat-grid"><StatCard label="Problems solved" value="24" note="↑ 4 this week" icon={Check} tone="stat-mint" /><StatCard label="Success rate" value="78%" note="↑ 6% from last week" icon={Target} tone="stat-purple" /><StatCard label="Current streak" value="7 days" note="Your best is 12 days" icon={Flame} tone="stat-amber" /><StatCard label="Interview reps" value="18" note="3 ready to revisit" icon={Lightbulb} tone="stat-blue" /></div><div className="dashboard-grid"><section className="panel progress-panel"><div className="panel-heading"><div><h2>Skill progress</h2><p>Your practice, topic by topic.</p></div><button className="text-btn" onClick={() => go("analytics")}>View analytics <ArrowRight size={14} /></button></div><div className="skill-list">{[["Arrays", 82], ["Strings", 68], ["HashMap", 61], ["Searching", 54], ["Stacks & Queues", 43], ["Dynamic Programming", 28]].map(([name, value]) => <div className="skill-row" key={name as string}><div><span>{name as string}</span><b>{value}%</b></div><div className="progress-track"><span style={{ width: `${value}%` }} /></div></div>)}</div></section><section className="panel activity-panel"><div className="panel-heading"><div><h2>Weekly activity</h2><p>7 problems this week</p></div><Pill tone="mint">On track</Pill></div><div className="activity-chart">{[["M", 36], ["T", 64], ["W", 48], ["T", 78], ["F", 52], ["S", 90], ["S", 26]].map(([day, height], i) => <div className="bar-col" key={`${day}${i}`}><div className={`bar ${i === 5 ? "bar-today" : ""}`} style={{ height: `${height}%` }}><span>{Math.round((height as number) / 12)}</span></div><small>{day}</small></div>)}</div></section></div><section className="panel recent-panel"><div className="panel-heading"><div><h2>Recent submissions</h2><p>Your latest attempts across the problem set.</p></div><button className="text-btn" onClick={() => go("history")}>View history <ArrowRight size={14} /></button></div><SubmissionTable compact /></section></div>;
}

function Problems({ go, selectProblem }: { go: (view: View) => void; selectProblem: (problem: Problem) => void }) {
  const [query, setQuery] = useState(""); const [difficulty, setDifficulty] = useState("All"); const [topic, setTopic] = useState("All topics"); const [status, setStatus] = useState("All");
  const filtered = useMemo(() => problems.filter(p => p.title.toLowerCase().includes(query.toLowerCase()) && (difficulty === "All" || p.difficulty === difficulty) && (topic === "All topics" || p.topic === topic) && (status === "All" || (status === "Solved" ? p.solved : !p.solved))), [query, difficulty, topic, status]);
  return <div className="screen"><div className="screen-heading"><div><div className="section-kicker">THE PROBLEM SET</div><h1>Find your next win.</h1><p>Small steps, clear explanations, better interviews.</p></div><button className="btn btn-primary" onClick={() => selectProblem(problems[0])}><Play size={15} /> Random problem</button></div><div className="filter-bar"><label className="search-box"><Search size={16} /><input placeholder="Search problems" value={query} onChange={e => setQuery(e.target.value)} /></label><select value={difficulty} onChange={e => setDifficulty(e.target.value)}><option>All</option><option>Easy</option><option>Medium</option><option>Hard</option></select><select value={topic} onChange={e => setTopic(e.target.value)}><option>All topics</option>{Array.from(new Set(problems.map(p => p.topic))).map(t => <option key={t}>{t}</option>)}</select><select value={status} onChange={e => setStatus(e.target.value)}><option>All</option><option>Solved</option><option>Unsolved</option></select><button className="filter-icon"><ListFilter size={17} /></button></div><div className="problem-summary"><span><b>{filtered.length}</b> problems</span><span><Check size={14} /> 3 completed today</span><span className="summary-spacer" /><span className="sort-label">Sort by <b>Recommended <ChevronDown size={14} /></b></span></div><div className="problem-table"><div className="problem-head"><span>PROBLEM</span><span>TOPIC</span><span>DIFFICULTY</span><span>ATTEMPTS</span><span>STATUS</span><span /></div>{filtered.map(p => <button className="problem-row" key={p.title} onClick={() => selectProblem(p)}><span className="problem-name"><span className={`problem-status ${p.solved ? "solved" : ""}`}>{p.solved ? <Check size={13} /> : <span />}</span><b>{p.title}</b></span><span><Pill>{p.topic}</Pill></span><span><span className={`difficulty ${p.difficulty.toLowerCase()}`}>{p.difficulty}</span></span><span className="muted">{p.attempts}</span><span>{p.solved ? <Pill tone="mint">Solved</Pill> : <span className="muted">Not started</span>}</span><ArrowRight size={16} className="row-arrow" /></button>)}</div></div>;
}

function Practice({ problem, onSubmit }: { problem: Problem; onSubmit: (submittedCode: string, result: ExecutionResult) => void }) {
  const detail = getProblemDetails(problem);
  const [editor, setEditor] = useState(detail.starterCode); const [consoleTab, setConsoleTab] = useState("Output"); const [execution, setExecution] = useState<ExecutionResult | null>(null);
  return <div className="screen practice-screen"><div className="practice-top"><div><div className="section-kicker">PRACTICE ROOM / {problem.topic.toUpperCase()}</div><h1>{problem.title}</h1><div className="practice-meta"><Pill tone={problem.difficulty === "Easy" ? "mint" : problem.difficulty === "Medium" ? "amber" : "purple"}>{problem.difficulty}</Pill><Pill>{problem.topic}</Pill><span><Clock3 size={14} /> Est. 15 min</span></div></div><div className="practice-nav"><button>‹ Previous</button><span>Practice mode</span><button>Next ›</button></div></div><div className="workspace"><article className="problem-statement"><div className="statement-tabs"><b>Problem</b><span>Hints <span className="hint-count">2</span></span></div><h2>{problem.title}</h2><p>{detail.statement}</p><div className="statement-block"><h3>Example</h3><div className="example"><div><span>Input</span><code>{detail.input}</code></div><div><span>Output</span><code>{detail.output}</code></div><div><span>Why</span><p>{detail.why}</p></div></div></div><div className="statement-block"><h3>Constraints</h3><ul>{detail.constraints.map(constraint => <li key={constraint}>{constraint}</li>)}</ul></div><div className="concept-note"><Lightbulb size={17} /><span><b>Interview lens</b><small>{detail.lens}</small></span></div></article><section className="editor-panel"><div className="editor-toolbar"><div className="language-select"><span className="java-dot">J</span> Java <ChevronDown size={14} /></div><div className="editor-actions"><button className="editor-reset" onClick={() => { setEditor(detail.starterCode); setExecution(null); }}><RotateCcw size={14} /> Reset</button><button className="btn btn-run" onClick={() => { setExecution(evaluateCode(editor, problem, detail)); setConsoleTab("Output"); }}><Play size={14} /> Run</button><button className="btn btn-submit" onClick={() => { const result = evaluateCode(editor, problem, detail); setExecution(result); setConsoleTab("Output"); if (result.ok) onSubmit(editor, result); }}><Zap size={14} /> Submit</button></div></div><div className="code-editor"><div className="editor-lines">{editor.split("\n").map((_, i) => <span key={i}>{String(i + 1).padStart(2, "0")}</span>)}</div><textarea spellCheck={false} value={editor} onChange={e => setEditor(e.target.value)} /></div><div className="console"><div className="console-top"><span>CONSOLE</span>{["Input", "Output", "Compilation errors", "Runtime errors", "Execution time"].map(tab => <button className={consoleTab === tab ? "selected" : ""} key={tab} onClick={() => setConsoleTab(tab)}>{tab}{tab === "Output" && execution?.ok && <i />}</button>)}</div><div className="console-body">{consoleTab === "Input" && <pre>{detail.input}</pre>}{consoleTab === "Output" && <>{execution ? execution.ok ? <><div className="console-success"><Check size={14} /> Sample test passed · {execution.time}</div><pre>{execution.output}</pre></> : <><div className="console-error"><X size={14} /> {execution.error}</div>{execution.output && <pre>Expected sample output: {execution.output}</pre>}</> : <div className="console-placeholder"><Terminal size={20} /><span>Run your code to compile and test the sample.</span></div>}</>}{consoleTab === "Compilation errors" && <div className="console-placeholder"><Check size={20} /><span>No compilation errors.</span></div>}{consoleTab === "Runtime errors" && <div className="console-placeholder"><Check size={20} /><span>No runtime errors.</span></div>}{consoleTab === "Execution time" && <pre>{problem.time === "—" ? "48 ms · 14 MB memory" : `${problem.time} · 12 MB memory`}</pre>}</div></div></section></div></div>;
}

function Analysis({ problem, submittedCode, go }: { problem: Problem; submittedCode: string; go: (view: View) => void }) {
  const detail = getProblemDetails(problem);
  return <div className="screen analysis-screen"><div className="analysis-hero"><div><div className="section-kicker">SUBMISSION #2048 · JUST NOW</div><h1>Solution accepted <span className="accepted-mark"><Check size={20} /></span></h1><p>{problem.title} is accepted. Now turn the pass into an explanation you can use in an interview.</p></div><button className="btn btn-primary interview-jump" onClick={() => document.getElementById("interview-questions")?.scrollIntoView({ behavior: "smooth" })}>Practice interview questions <ArrowRight size={14} /></button><div className="accepted-stats"><span><b>5 / 5</b><small>Test cases</small></span><span><b>{problem.time === "—" ? "48 ms" : problem.time}</b><small>Execution time</small></span><span><b>12 MB</b><small>Memory</small></span></div></div><div className="analysis-grid"><div className="analysis-main"><section className="panel"><div className="panel-heading"><div><div className="section-kicker">YOUR SOLUTION</div><h2>What your code does</h2></div><Pill tone="mint">{detail.time} · Guided</Pill></div><p className="analysis-copy">Your starter is set up for the {problem.title} pattern. Use the explanation below to connect the code you wrote with the data structure and invariant that make this approach work.</p><div className="complexity-row"><div><span>Time complexity</span><b>{detail.time}</b><small>Optimal target for this problem</small></div><div><span>Space complexity</span><b>{detail.space}</b><small>Auxiliary memory for the approach</small></div></div><div className="concept-chips"><span>{problem.topic}</span><span>{problem.title}</span><span>Java</span></div></section><section className="panel code-review"><div className="panel-heading"><div><div className="section-kicker">SUBMITTED CODE</div><h2>solution.java</h2></div><button className="text-btn">Copy code</button></div><pre>{submittedCode}</pre></section><div className="two-col"><section className="panel strength-card"><div className="mini-heading"><span className="mini-icon mint"><Check size={15} /></span><h3>What to explain well</h3></div><ul><li>State the invariant your loop or pointers maintain.</li><li>Explain why the chosen data structure fits {problem.title}.</li><li>Call out the {detail.time} time target.</li></ul></section><section className="panel improve-card"><div className="mini-heading"><span className="mini-icon amber"><Lightbulb size={15} /></span><h3>Coach prompt</h3></div><p>{detail.lens}</p></section></div></div><aside className="analysis-side"><div className="coach-card"><div className="coach-top"><span className="coach-spark"><Sparkles size={16} /></span><span>COACH NOTE</span></div><h3>Your next rep is an explanation.</h3><p>Compare the simple baseline with the {problem.title} pattern, then rehearse the questions generated specifically for this problem.</p><button className="btn btn-light" onClick={() => document.getElementById("interview-questions")?.scrollIntoView({ behavior: "smooth" })}>Open questions <ArrowRight size={14} /></button></div><div className="panel next-card"><div className="section-kicker">KEEP GOING</div><h3>Build the full interview answer.</h3><div className="next-item"><span className="next-number">01</span><span><b>Compare approaches</b><small>{detail.brute} </small></span><ArrowRight size={15} /></div><div className="next-item"><span className="next-number">02</span><span><b>Practice your answer</b><small>{detail.questions.length} questions generated for {problem.title}</small></span><ArrowRight size={15} /></div></div></aside></div><section className="panel comparison-panel"><div className="panel-heading"><div><div className="section-kicker">THINK LIKE AN INTERVIEWER</div><h2>Compare the approaches</h2><p>Understanding the “why” is where the signal is.</p></div><GitCompareArrows size={22} /></div><div className="approach-cards"><div className="approach"><div className="approach-title"><span className="approach-icon brute">01</span><span><b>Baseline approach</b><small>Start simple</small></span><Pill tone="amber">Slower</Pill></div><p>{detail.brute}</p></div><div className="approach approach-highlight"><div className="approach-title"><span className="approach-icon optimal">02</span><span><b>Interview-ready approach</b><small>Use the right pattern</small></span><Pill tone="mint">{detail.time}</Pill></div><p>{detail.optimal}</p></div></div><table className="comparison-table"><thead><tr><th>Approach</th><th>Time</th><th>Space</th><th>Performance</th></tr></thead><tbody><tr><td>Baseline</td><td>Varies</td><td>Varies</td><td><span className="performance low">Baseline</span></td></tr><tr><td>Your solution target</td><td>{detail.time}</td><td>{detail.space}</td><td><span className="performance excellent">Interview-ready</span></td></tr></tbody></table></section><section className="panel interview-panel" id="interview-questions"><div className="panel-heading"><div><div className="section-kicker">INTERVIEW PREP / {problem.title.toUpperCase()}</div><h2>Questions you should be ready for</h2><p>These prompts are specific to the problem you just solved.</p></div><Pill tone="purple">{detail.questions.length} questions</Pill></div>{detail.questions.map((item, i) => <details className="question" key={item.question} open={i === 0}><summary><span>Q{i + 1}</span><b>{item.question}</b><ChevronDown size={16} /></summary><div className="answer"><strong>Model answer</strong><p>{item.answer}</p></div></details>)}</section></div>;
}

function Analytics() { return <div className="screen"><div className="screen-heading"><div><div className="section-kicker">PERFORMANCE ANALYTICS</div><h1>Make your progress visible.</h1><p>Patterns in your practice become your plan.</p></div><select className="range-select"><option>Last 30 days</option><option>Last 90 days</option></select></div><div className="analytics-grid"><section className="panel large-chart"><div className="panel-heading"><div><h2>Problems solved</h2><p>24 total · 8 this month</p></div><Pill tone="mint">↑ 32%</Pill></div><div className="line-chart"><div className="chart-y"><span>10</span><span>8</span><span>6</span><span>4</span><span>2</span><span>0</span></div><div className="chart-area"><div className="chart-gridlines">{[1, 2, 3, 4, 5].map(n => <i key={n} />)}</div><svg viewBox="0 0 600 220" preserveAspectRatio="none"><path d="M0,190 C40,180 48,160 85,170 S130,120 165,138 S205,90 245,112 S290,80 330,102 S375,45 415,78 S465,65 500,42 S550,58 600,18" fill="none" stroke="currentColor" strokeWidth="3" /><path d="M0,190 C40,180 48,160 85,170 S130,120 165,138 S205,90 245,112 S290,80 330,102 S375,45 415,78 S465,65 500,42 S550,58 600,18 V220 H0Z" fill="url(#fill)" opacity=".18" /><defs><linearGradient id="fill" x1="0" x2="0" y1="0" y2="1"><stop stopColor="#c8f56a" /><stop offset="1" stopColor="#c8f56a" stopOpacity="0" /></linearGradient></defs></svg><div className="chart-x"><span>Sep 08</span><span>Sep 15</span><span>Sep 22</span><span>Sep 29</span><span>Oct 07</span></div></div></div></section><section className="panel topic-panel"><div className="panel-heading"><div><h2>Topic coverage</h2><p>Where your reps are going</p></div><Network size={20} /></div>{[["Arrays", 82, "#c8f56a"], ["Strings", 68, "#b9a1ff"], ["Searching", 54, "#ffca6b"], ["HashMap", 61, "#8bd4ff"], ["DP", 28, "#ff9f9f"]].map(([n, v, c]) => <div className="topic-row" key={n as string}><div><span>{n as string}</span><b>{v}%</b></div><div className="topic-track"><span style={{ width: `${v}%`, background: c as string }} /></div></div>)}</section></div><div className="analytics-bottom"><section className="panel interview-score"><div className="panel-heading"><div><h2>Interview readiness</h2><p>Based on problem explanations and reps.</p></div><Trophy size={20} /></div><div className="readiness"><div className="readiness-score">72<small>/100</small></div><div className="readiness-copy"><b>Good momentum</b><p>Practice 3 more medium problems and revisit your complexity explanations.</p><div className="progress-track"><span style={{ width: "72%" }} /></div></div></div></section><section className="panel focus-panel"><div className="section-kicker">NEXT BEST ACTION</div><h3>Strengthen Dynamic Programming</h3><p>You have 28% coverage here. One focused problem today keeps the gap from growing.</p><button className="btn btn-dark">Practice a DP problem <ArrowRight size={14} /></button></section></div></div>; }

function SubmissionTable({ compact = false }: { compact?: boolean }) { const rows = problems.filter(p => p.solved).slice(0, compact ? 4 : 8); return <div className="submission-table"><div className="submission-head"><span>PROBLEM</span><span>STATUS</span><span>TIME</span><span>DATE</span><span /></div>{rows.map((p, i) => <div className="submission-row" key={p.title}><span className="problem-name"><span className="problem-status solved"><Check size={13} /></span><b>{p.title}</b></span><span><Pill tone="mint">Accepted</Pill></span><span className="muted">{p.time}</span><span className="muted">{i === 0 ? "Today" : `${i + 1}d ago`}</span><ArrowRight size={15} className="row-arrow" /></div>)}</div>; }
function HistoryPage() { return <div className="screen"><div className="screen-heading"><div><div className="section-kicker">YOUR TRAIL</div><h1>Submission history.</h1><p>Every attempt is a breadcrumb toward confidence.</p></div><button className="btn btn-ghost"><History size={15} /> Export history</button></div><div className="history-summary"><div><span className="history-icon mint"><Check size={17} /></span><span><b>24</b><small>Accepted submissions</small></span></div><div><span className="history-icon purple"><Activity size={17} /></span><span><b>31</b><small>Total attempts</small></span></div><div><span className="history-icon amber"><Clock3 size={17} /></span><span><b>3h 42m</b><small>Practice time</small></span></div></div><section className="panel history-panel"><div className="panel-heading"><div><h2>All submissions</h2><p>Most recent first.</p></div><div className="history-filters"><button className="active">All</button><button>Accepted</button><button>Needs review</button></div></div><SubmissionTable /></section></div>; }

const routeViews: View[] = ["home", "login", "signup", "dashboard", "problems", "practice", "analysis", "analytics", "history"];
const viewFromPath = (): View => { const candidate = window.location.pathname.replace(/^\//, "") as View; return routeViews.includes(candidate) ? candidate : "home"; };

export default function App() { const [view, setView] = useState<View>(viewFromPath); const [currentUser, setCurrentUser] = useState<StoredUser | null>(readStoredUser); const [selectedProblem, setSelectedProblem] = useState<Problem>(problems[0]); const [submittedCode, setSubmittedCode] = useState(problemDetails["Two Sum"].starterCode); const go = (next: View) => { window.history.pushState({}, "", next === "home" ? "/" : `/${next}`); setView(next); }; const handleAuth = (user: StoredUser) => { setCurrentUser(user); go("dashboard"); }; const logout = () => { localStorage.removeItem(USER_STORAGE_KEY); setCurrentUser(null); go("home"); }; const selectProblem = (problem: Problem) => { setSelectedProblem(problem); setSubmittedCode(getProblemDetails(problem).starterCode); go("practice"); }; if (view === "login" || view === "signup") return <AuthPage mode={view} go={go} onAuth={handleAuth} />; if (view === "home") return <Home go={go} />; return <AppShell view={view} setView={go} user={currentUser} onLogout={logout}>{view === "dashboard" && <Dashboard go={go} user={currentUser} />}{view === "problems" && <Problems go={go} selectProblem={selectProblem} />}{view === "practice" && <Practice key={selectedProblem.title} problem={selectedProblem} onSubmit={(nextCode) => { setSubmittedCode(nextCode); go("analysis"); }} />}{view === "analysis" && <Analysis problem={selectedProblem} submittedCode={submittedCode} go={go} />}{view === "analytics" && <Analytics />}{view === "history" && <HistoryPage />}</AppShell>; }
